// Anti-pattern: setting without finally remove() pins RequestContext on all 200 Tomcat threads
CTX.set(parsedContext);
handleRequest(); // if this throws or forgets remove(), User A's context stays on the thread!

import java.util.concurrent.Executor;

public final class RequestContextHolder {
    private static final ThreadLocal<RequestContext> CTX = new ThreadLocal<>();
    public static void set(RequestContext ctx) { CTX.set(ctx); }
    public static RequestContext get() { return CTX.get(); }
    public static void clear() { CTX.remove(); }
}

public final class ContextPropagatingExecutor implements Executor {
    private final Executor delegate;
    public ContextPropagatingExecutor(Executor delegate) { this.delegate = delegate; }

    @Override
    public void execute(Runnable task) {
        RequestContext captured = RequestContextHolder.get();
        delegate.execute(() -> {
            RequestContext prior = RequestContextHolder.get();
            try {
                if (captured != null) RequestContextHolder.set(captured);
                else RequestContextHolder.clear();
                task.run();
            } finally {
                if (prior != null) RequestContextHolder.set(prior);
                else RequestContextHolder.clear();
            }
        });
    }
}

private static final ScopedValue<RequestContext> CTX = ScopedValue.newInstance();

// Automatically unbound when lambda exits or throws
ScopedValue.where(CTX, parsedContext).run(() -> chain.doFilter(req, res));

// Configure ThreadPoolExecutor to expire idle threads if a 3rd-party lib leaks ThreadLocals
ThreadPoolExecutor pool = new ThreadPoolExecutor(
    0, 32, 60L, TimeUnit.SECONDS, new ArrayBlockingQueue<>(256)
);
pool.allowCoreThreadTimeOut(true);

// Filter guard in test/staging to catch any leaked context immediately
if (RequestContextHolder.get() != null) {
    throw new IllegalStateException("ThreadLocal RequestContext leaked across request boundary!");
}
